/**
 * Pure (no I/O) guards for PROVISION's first boot. Unit tested in
 * test/provision-first-boot.test.ts; the RCA that motivated every function here
 * is docs/PROVISIONING-FIRST-BOOT-RCA-2026-10-02.md.
 *
 *   1. Private-IP inventory of a node, read from its real VM/CT configs, so IPAM
 *      never hands out an address some VM on that node is already configured
 *      with (valheim-gjjrv9 / VM 644 got 10.20.1.101 on node-2 while VMs 101,
 *      137 and 138 were configured with the same address; NAT then delivered the
 *      platform's SSH to VM 101).
 *   2. Guest identity: is the machine SSH reached the VM we just built?
 *   3. Early crash-loop classification from the guest's own evidence, with the
 *      game's own last error lines (projectzomboid-syep3t: `invalid username
 *      given to "-adminusername"` every ~30 s, which the old code only noticed
 *      after the full 5-minute port window, three times over).
 *   4. Secret redaction for anything copied from a guest log into Job.error.
 */

// ---------------------------------------------------------------------------
// 1. Node IP inventory
// ---------------------------------------------------------------------------

export type VmConfigLike = Record<string, unknown>;

export type VmIpEntry = {
  vmid: number;
  /** "qemu" | "lxc" — reported only. */
  kind: string;
  name?: string | null;
  status?: string | null;
  /** IPv4 addresses the config assigns (ipconfigN `ip=` on qemu, netN `ip=` on lxc). */
  ips: string[];
  /** Lower-cased MACs from netN, for ARP correlation. */
  macs: string[];
};

const IPV4_RE = /^(?:25[0-5]|2[0-4]\d|1?\d?\d)(?:\.(?:25[0-5]|2[0-4]\d|1?\d?\d)){3}$/;

export function isIpv4(s: unknown): s is string {
  return typeof s === "string" && IPV4_RE.test(s);
}

/**
 * Every IPv4 a Proxmox VM/CT config assigns. qemu: `ipconfigN: ip=10.20.1.101/24,gw=…`;
 * lxc: `netN: name=eth0,…,ip=10.20.1.5/24`. `ip=dhcp` / `ip6=` are ignored.
 */
export function ipsFromVmConfig(cfg: VmConfigLike | null | undefined): string[] {
  if (!cfg || typeof cfg !== "object") return [];
  const out = new Set<string>();
  for (const [k, v] of Object.entries(cfg)) {
    if (typeof v !== "string") continue;
    if (!/^(ipconfig|net)\d+$/.test(k)) continue;
    for (const part of v.split(",")) {
      const m = /^ip=([^/\s]+)(?:\/\d+)?$/.exec(part.trim());
      if (m && isIpv4(m[1])) out.add(m[1]);
    }
  }
  return [...out];
}

/** MACs a config's netN lines carry (`virtio=BC:24:11:…,bridge=vmbr1` or lxc `hwaddr=`). */
export function macsFromVmConfig(cfg: VmConfigLike | null | undefined): string[] {
  if (!cfg || typeof cfg !== "object") return [];
  const out = new Set<string>();
  for (const [k, v] of Object.entries(cfg)) {
    if (typeof v !== "string" || !/^net\d+$/.test(k)) continue;
    for (const part of v.split(",")) {
      const m = /^(?:[a-z0-9]+|hwaddr)=((?:[0-9A-Fa-f]{2}:){5}[0-9A-Fa-f]{2})$/.exec(part.trim());
      if (m) out.add(m[1].toLowerCase());
    }
  }
  return [...out];
}

/** ip -> vmids, only for addresses configured on MORE than one VM/CT. */
export function duplicatePrivateIps(entries: readonly VmIpEntry[]): Map<string, number[]> {
  const by = new Map<string, number[]>();
  for (const e of entries) for (const ip of e.ips) by.set(ip, [...(by.get(ip) ?? []), e.vmid]);
  const dup = new Map<string, number[]>();
  for (const [ip, ids] of by) if (ids.length > 1) dup.set(ip, [...new Set(ids)].sort((a, b) => a - b));
  return dup;
}

/** VMs/CTs OTHER than `selfVmid` whose config assigns `ip`. */
export function vmsHoldingIp(entries: readonly VmIpEntry[], ip: string, selfVmid?: number | null): number[] {
  return entries.filter((e) => e.vmid !== selfVmid && e.ips.includes(ip)).map((e) => e.vmid);
}

export type NeighborEntry = { ip: string; mac?: string | null; state?: string | null };

/**
 * Addresses the node's neighbour (ARP) table shows as actually answering. A
 * FAILED/INCOMPLETE entry is a lookup that got no answer — not "in use".
 */
export function liveNeighborIps(entries: readonly NeighborEntry[] | null | undefined): Set<string> {
  const out = new Set<string>();
  for (const n of entries ?? []) {
    if (!isIpv4(n.ip)) continue;
    const st = String(n.state ?? "").toUpperCase();
    if (/FAILED|INCOMPLETE|NOARP/.test(st)) continue;
    if (!n.mac) continue;
    out.add(n.ip);
  }
  return out;
}

/**
 * The set of private IPs on a node that IPAM must treat as taken in addition
 * to the DB: every address any VM/CT config assigns, every live ARP neighbour.
 * `exceptVmid` is the VM being (re)configured itself (its own config may
 * already carry the address on a retry).
 */
export function nodeHeldIps(
  entries: readonly VmIpEntry[],
  neighbors: readonly NeighborEntry[] | null | undefined,
  exceptVmid?: number | null,
): Set<string> {
  const out = new Set<string>();
  for (const e of entries) if (e.vmid !== exceptVmid) for (const ip of e.ips) out.add(ip);
  // ARP: an IP whose MAC belongs to the VM being configured is not "someone else".
  const ownMacs = new Set(entries.filter((e) => e.vmid === exceptVmid).flatMap((e) => e.macs));
  for (const n of neighbors ?? []) {
    if (!liveNeighborIps([n]).has(n.ip)) continue;
    if (n.mac && ownMacs.has(n.mac.toLowerCase())) continue;
    out.add(n.ip);
  }
  return out;
}

/**
 * Why `ip` cannot be (re)used for `selfVmid`, or null if it is free on the node.
 * Used on a RETRY too: the address already on the Server row is re-checked, so a
 * collision introduced by anything (an orphan VM, a restore, a manual clone) is
 * caught before the VM is started with it.
 */
export function ipConflictReason(
  ip: string,
  selfVmid: number | null | undefined,
  entries: readonly VmIpEntry[],
  neighbors: readonly NeighborEntry[] | null | undefined,
): string | null {
  const holders = vmsHoldingIp(entries, ip, selfVmid);
  if (holders.length) return `${ip} is already configured on VM ${holders.join(", ")} on this node`;
  const ownMacs = new Set(entries.filter((e) => e.vmid === selfVmid).flatMap((e) => e.macs));
  for (const n of neighbors ?? []) {
    if (n.ip !== ip || !liveNeighborIps([n]).has(ip)) continue;
    if (n.mac && ownMacs.has(n.mac.toLowerCase())) continue;
    return `${ip} is answering ARP on this node from MAC ${n.mac} (not VM ${selfVmid ?? "?"})`;
  }
  return null;
}

// ---------------------------------------------------------------------------
// 2. Guest identity
// ---------------------------------------------------------------------------

/** `smbios1: uuid=1234-…,manufacturer=…` → lower-case uuid, or null. */
export function smbiosUuid(smbios1: unknown): string | null {
  if (typeof smbios1 !== "string") return null;
  const m = /(?:^|,)uuid=([0-9a-fA-F-]{36})(?:,|$)/.exec(smbios1);
  return m ? m[1].toLowerCase() : null;
}

export type IdentityVerdict = { ok: true; how: "uuid" | "hostname" | "unverified" } | { ok: false; reason: string };

/**
 * Is the guest SSH reached the VM we expect? The SMBIOS product UUID is the
 * strong signal (Proxmox writes it into the VM config and the guest kernel
 * exposes it at /sys/class/dmi/id/product_uuid); the hostname (cloud-init sets
 * it to the Proxmox VM name = Server.hostname) is the fallback. Neither readable
 * → "unverified" (proceed, logged), never a guess.
 */
export function guestIdentityVerdict(input: {
  expectedUuid: string | null;
  expectedHostname: string | null;
  gotUuid: string | null;
  gotHostname: string | null;
}): IdentityVerdict {
  const eu = input.expectedUuid?.trim().toLowerCase() || null;
  const gu = input.gotUuid?.trim().toLowerCase() || null;
  if (eu && gu) {
    if (eu === gu) return { ok: true, how: "uuid" };
    return {
      ok: false,
      reason: `the machine that answered SSH has SMBIOS UUID ${gu}, but this VM's is ${eu}`,
    };
  }
  const short = (h: string | null) => (h ?? "").trim().toLowerCase().split(".")[0] || null;
  const eh = short(input.expectedHostname);
  const gh = short(input.gotHostname);
  if (eh && gh) {
    if (eh === gh) return { ok: true, how: "hostname" };
    return { ok: false, reason: `the machine that answered SSH is named "${gh}", but this VM is "${eh}"` };
  }
  return { ok: true, how: "unverified" };
}

/** Read-only, shell-inert command that prints the guest's identity markers. */
export const GUEST_IDENTITY_CMD =
  `printf 'NXID_UUID=%s\\n' "$(cat /sys/class/dmi/id/product_uuid 2>/dev/null)"; ` +
  `printf 'NXID_HOST=%s\\n' "$(hostname 2>/dev/null)"`;

export function parseGuestIdentity(stdout: string): { uuid: string | null; hostname: string | null } {
  const uuid = /NXID_UUID=([0-9A-Fa-f-]{36})/.exec(stdout)?.[1] ?? null;
  const hostname = /NXID_HOST=([A-Za-z0-9.-]{1,253})/.exec(stdout)?.[1] ?? null;
  return { uuid, hostname };
}

// ---------------------------------------------------------------------------
// 3. Game startup classification
// ---------------------------------------------------------------------------

/**
 * Lines that mean "this game will not start with this configuration" rather
 * than "still installing". Generic on purpose — matched against the game's own
 * output, so a new family's fatal message is still surfaced in the tail even
 * when no pattern matches.
 */
export const FATAL_LINE_PATTERNS: readonly RegExp[] = [
  /invalid username/i,
  /invalid (?:password|argument|value|config)/i,
  /\bServer exited\b/i,
  /Aborting server start/i,
  /\bMissing [A-Z][A-Z0-9_]{2,}\b/,
  /is required/i,
  /Exception in thread "main"/,
  /\bFATAL\b|\bPANIC\b/,
  /error while loading shared libraries/i,
  /Unable to find image|pull access denied|manifest unknown|toomanyrequests|rate limit/i,
  /No such container/i,
  /no space left on device/i,
  /There is insufficient memory|OutOfMemoryError|Killed process/i,
  /Error response from daemon/i,
  /password must be at least|password.*(?:too short|contains)/i,
];

export function isFatalLine(line: string): boolean {
  return FATAL_LINE_PATTERNS.some((re) => re.test(line));
}

/** The fatal lines of a log (deduped, last `max`), or — if none matched — its non-empty tail. */
export function lastErrorLines(log: string, max = 8): { lines: string[]; matched: boolean } {
  const all = String(log ?? "")
    // eslint-disable-next-line no-control-regex
    .replace(/\x1b\[[0-9;]*[A-Za-z]/g, "")
    .split(/\r?\n/)
    .map((l) => l.trim())
    .filter(Boolean);
  const fatal: string[] = [];
  for (const l of all) if (isFatalLine(l) && !fatal.includes(l)) fatal.push(l);
  if (fatal.length) return { lines: fatal.slice(-max), matched: true };
  return { lines: all.slice(-max), matched: false };
}

export type StartupSample = {
  /** systemd NRestarts of the game unit, -1 unknown. */
  restarts: number;
  /** docker container state ("running" | "exited" | "restarting" | "created" | "missing" | "unknown"). */
  container: string;
  exitCode: number | null;
  /** Seconds the container's last run lasted (FinishedAt - StartedAt), null if unknown/running. */
  lastRunSeconds: number | null;
  /** Last line of /var/lib/nxeon/game-setup.state ("" when absent). */
  setupState: string;
  /** Is the in-guest setup script still running (pgrep)? */
  setupRunning: boolean;
  /** Recent game output (journal of the unit + docker logs tail). */
  log: string;
  /** Recent setup log tail (for setup failures). */
  setupLog?: string;
};

export type StartupVerdict =
  | { kind: "ok" }
  /** Keep waiting — nothing conclusive. */
  | { kind: "wait" }
  /** The in-guest setup died/failed before creating the container — re-run it (idempotent). */
  | { kind: "repair"; reason: string; lines: string[] }
  /** The game itself cannot start with this config — stop waiting now. */
  | { kind: "fatal"; reason: string; lines: string[] };

/** Restarts of the unit since the check began that make an exit loop conclusive without a known fatal line. */
export const EARLY_CRASH_RESTARTS = 3;
/** With a recognisable fatal line in the output, two restarts are enough. */
export const EARLY_CRASH_RESTARTS_WITH_FATAL = 2;
/** A run shorter than this that ends is "exited on start". */
export const SHORT_RUN_SECONDS = 90;

/**
 * Decide, from one in-guest sample and the restart counter seen when the check
 * began, whether waiting longer can help. Positive evidence only: unknown
 * readings never produce "fatal".
 */
export function classifyStartup(baselineRestarts: number, s: StartupSample): StartupVerdict {
  const state = (s.setupState ?? "").trim();
  if (s.container === "missing") {
    if (s.setupRunning) return { kind: "wait" };
    const setupTail = lastErrorLines(s.setupLog ?? "", 8);
    if (/\bfailed\b/i.test(state) || state === "" || !/\bready\b/.test(state)) {
      return {
        kind: "repair",
        reason:
          `the game container was never created (setup ${state ? `state "${state.replace(/^\S+\s+/, "")}"` : "left no state"}` +
          `${/No such container/i.test(s.log) ? "; the service is restarting against a container that does not exist" : ""})`,
        lines: setupTail.lines,
      };
    }
  }
  if (s.restarts < 0 || baselineRestarts < 0) return { kind: "wait" };
  const delta = s.restarts - baselineRestarts;
  const errs = lastErrorLines(s.log, 8);
  const exitedFast = s.container !== "running" && s.lastRunSeconds !== null && s.lastRunSeconds < SHORT_RUN_SECONDS;
  if ((errs.matched && delta >= EARLY_CRASH_RESTARTS_WITH_FATAL) || delta >= EARLY_CRASH_RESTARTS) {
    const how =
      s.exitCode === 0
        ? "exits (with code 0) seconds after every start"
        : s.exitCode !== null
          ? `exits with code ${s.exitCode} after every start`
          : "keeps exiting after start";
    return {
      kind: "fatal",
      reason:
        `the game ${how} — systemd has restarted it ${delta} time(s) while we watched` +
        `${exitedFast && s.lastRunSeconds !== null ? `, last run lasted ${s.lastRunSeconds}s` : ""}`,
      lines: errs.lines,
    };
  }
  return { kind: "wait" };
}

/**
 * One read-only command that samples everything `classifyStartup` needs.
 * `unit` and `container` must already be validated (SERVICE_RE / container
 * charset) — both come from our own control spec / catalog, never the customer.
 */
export function startupProbeCommand(unit: string, container: string): string {
  if (!/^[a-z0-9][a-z0-9_.-]{0,63}$/.test(unit)) throw new Error(`unsafe unit name: ${unit}`);
  if (!/^[A-Za-z0-9_.-]{1,64}$/.test(container)) throw new Error(`unsafe container name: ${container}`);
  return [
    `nr=$(systemctl show ${unit} -p NRestarts --value 2>/dev/null); case "$nr" in ''|*[!0-9]*) nr=-1;; esac`,
    `if docker container inspect ${container} >/dev/null 2>&1; then ` +
      `cs=$(docker inspect -f '{{.State.Status}}|{{.State.ExitCode}}|{{.State.StartedAt}}|{{.State.FinishedAt}}' ${container} 2>/dev/null); ` +
      `else if docker info >/dev/null 2>&1; then cs='missing|||'; else cs='unknown|||'; fi; fi`,
    `st=$(tail -n 1 /var/lib/nxeon/game-setup.state 2>/dev/null)`,
    `if pgrep -f 'nxeon-(game-)?setup\\.sh' >/dev/null 2>&1; then sr=1; else sr=0; fi`,
    `echo "NXSU_NR=$nr"; echo "NXSU_CS=$cs"; echo "NXSU_ST=$st"; echo "NXSU_SR=$sr"`,
    `echo NXSU_LOG_BEGIN; journalctl -u ${unit} -n 40 --no-pager -o cat 2>/dev/null | tail -n 40; ` +
      `docker logs --tail 40 ${container} 2>&1 | tail -n 40; echo NXSU_LOG_END`,
    `echo NXSU_SLOG_BEGIN; tail -n 25 /var/log/nxeon-setup.log 2>/dev/null | grep -v '^+' ; echo NXSU_SLOG_END`,
  ].join("; ");
}

function isoSeconds(a: string, b: string): number | null {
  const s = Date.parse(a);
  const f = Date.parse(b);
  if (!Number.isFinite(s) || !Number.isFinite(f) || f < s || f < Date.parse("2001-01-01")) return null;
  return Math.round((f - s) / 1000);
}

export function parseStartupProbe(stdout: string): StartupSample | null {
  const nr = /NXSU_NR=(-?\d+)/.exec(stdout);
  const cs = /NXSU_CS=([a-z]*)\|(-?\d*)\|([^|\n]*)\|([^\n]*)/.exec(stdout);
  if (!nr || !cs) return null;
  const between = (a: string, b: string) => {
    const i = stdout.indexOf(a);
    const j = stdout.indexOf(b);
    return i >= 0 && j > i ? stdout.slice(i + a.length, j) : "";
  };
  const status = cs[1] || "unknown";
  return {
    restarts: Number(nr[1]),
    container: status,
    exitCode: cs[2] === "" ? null : Number(cs[2]),
    lastRunSeconds: status === "running" ? null : isoSeconds(cs[3], cs[4]),
    setupState: /NXSU_ST=([^\n]*)/.exec(stdout)?.[1]?.trim() ?? "",
    setupRunning: /NXSU_SR=1/.test(stdout),
    log: between("NXSU_LOG_BEGIN", "NXSU_LOG_END"),
    setupLog: between("NXSU_SLOG_BEGIN", "NXSU_SLOG_END"),
  };
}

// ---------------------------------------------------------------------------
// 4. Redaction
// ---------------------------------------------------------------------------

/** Values from a gameConfig that must never be copied out of a guest log. */
export function secretValuesFromConfig(cfg: Record<string, unknown> | null | undefined): string[] {
  const out: string[] = [];
  for (const [k, v] of Object.entries(cfg ?? {})) {
    if (typeof v !== "string" || v.length < 4) continue;
    if (/PASS|PW|TOKEN|SECRET|KEY|LICEN[CS]E/i.test(k)) out.push(v);
  }
  return out;
}

export function redactSecrets(text: string, secrets: readonly (string | null | undefined)[]): string {
  let out = text;
  for (const s of secrets) if (s && s.length >= 4) out = out.split(s).join("***");
  // Generic `PASSWORD=…`/`-adminpassword x` shapes, whatever the value.
  out = out.replace(/((?:PASS(?:WORD)?|PASSWD|PW|TOKEN|SECRET)[A-Z_]*\s*[=:]\s*)\S+/gi, "$1***");
  out = out.replace(/(-(?:admin)?password\s+)\S+/gi, "$1***");
  return out;
}

/** Format lines for Job.error: indented, each capped, total capped. */
export function formatGuestLines(lines: readonly string[], secrets: readonly (string | null | undefined)[] = []): string {
  return lines
    .map((l) => `  | ${redactSecrets(l, secrets).slice(0, 240)}`)
    .join("\n")
    .slice(0, 1400);
}

