/**
 * In-guest steps of PROVISION's first boot that need SSH, written against a
 * tiny injectable shell (`GuestShell`) so test/provision-first-boot.test.ts can
 * replay both 2026-10-02 incidents against a fake guest. No DB access here.
 *
 * Every remote command is a fixed string or built from values validated by
 * lib/provision-guard.ts; the only data passed on STDIN is the management
 * PUBLIC key and our own generated setup script. Nothing long runs inside one
 * SSH exec: the game setup is launched DETACHED (systemd-run, falling back to
 * setsid+nohup) and then observed with short reads.
 *
 * See docs/PROVISIONING-FIRST-BOOT-RCA-2026-10-02.md.
 */
import {
  GUEST_IDENTITY_CMD,
  parseGuestIdentity,
  guestIdentityVerdict,
  parseStartupProbe,
  startupProbeCommand,
  type IdentityVerdict,
  type StartupSample,
} from "../lib/provision-guard";

export type ShellResult = { code: number | null; stdout: string; stderr: string };
export type GuestShell = {
  exec(cmd: string, timeoutMs: number): Promise<ShellResult>;
  execInput(cmd: string, input: string, timeoutMs: number): Promise<ShellResult>;
};
/** Open a connection with the stored credentials (management key, then password), run fn, close. */
export type WithGuest = <T>(fn: (sh: GuestShell) => Promise<T>) => Promise<T>;

/** Short SSH reads/writes only. */
export const GUEST_QUICK_MS = 12_000;
export const GUEST_WRITE_MS = 30_000;

export function isSshAuthError(e: unknown): boolean {
  const err = e as { level?: string; message?: string } | null;
  if (err?.level === "client-authentication") return true;
  return /All configured authentication methods failed|Authentication failed|permission denied \(publickey/i.test(String(err?.message ?? e ?? ""));
}

const PUBKEY_RE = /^ssh-ed25519 [A-Za-z0-9+/]+={0,2} [A-Za-z0-9_.@:-]{1,128}$/;

/** Idempotently make sure our management public key is in root's authorized_keys (key on STDIN). */
export const INSTALL_KEY_CMD =
  "umask 077; mkdir -p /root/.ssh && touch /root/.ssh/authorized_keys && chmod 700 /root/.ssh && chmod 600 /root/.ssh/authorized_keys && " +
  `k=$(head -c 2048) && { grep -qxF "$k" /root/.ssh/authorized_keys || printf '%s\\n' "$k" >> /root/.ssh/authorized_keys; } && echo NXKEY_OK`;

export type AccessResult =
  | { ok: true; repaired: boolean; keyInstalled: boolean }
  | { ok: false; authFailed: boolean; reason: string };

/**
 * Prove the stored credentials open the guest — and if the guest rejects them,
 * re-apply the stored root password through the QEMU guest agent (which talks
 * to the VM by vmid, so it can only ever reach the right machine) and try
 * again. Never mints new credentials: what is in the DB is what the guest gets.
 *
 * A guest that STILL rejects the credentials after the agent confirmed it set
 * them is not "slow": the SSH address is reaching a different machine. That is
 * exactly valheim-gjjrv9 (NAT -> 10.20.1.101 -> VM 101's MAC), and the reason
 * says so instead of "the guest stopped answering".
 */
export async function ensureGuestAccess(deps: {
  withGuest: WithGuest;
  reapplyCredentials: () => Promise<boolean>;
  managementPublicKey?: string | null;
  sleep?: (ms: number) => Promise<void>;
  /** Plain attempts before the agent repair — first boot may still be applying cloud-init. */
  attempts?: number;
  retryDelayMs?: number;
}): Promise<AccessResult> {
  const sleep = deps.sleep ?? ((ms: number) => new Promise((r) => setTimeout(r, ms)));
  const attempts = Math.max(1, deps.attempts ?? 4);
  const delay = deps.retryDelayMs ?? 15_000;
  const key = deps.managementPublicKey && PUBKEY_RE.test(deps.managementPublicKey.trim()) ? deps.managementPublicKey.trim() : null;

  const tryOnce = async (): Promise<{ ok: true; keyInstalled: boolean } | { ok: false; auth: boolean; msg: string }> => {
    try {
      const keyInstalled = await deps.withGuest(async (sh) => {
        if (!key) {
          await sh.exec("true", GUEST_QUICK_MS);
          return false;
        }
        const r = await sh.execInput(INSTALL_KEY_CMD, `${key}\n`, GUEST_QUICK_MS);
        return /NXKEY_OK/.test(r.stdout);
      });
      return { ok: true, keyInstalled };
    } catch (e) {
      return { ok: false, auth: isSshAuthError(e), msg: String((e as Error)?.message ?? e).slice(0, 200) };
    }
  };

  let last: { ok: false; auth: boolean; msg: string } | null = null;
  for (let i = 0; i < attempts; i++) {
    const r = await tryOnce();
    if (r.ok) return { ok: true, repaired: false, keyInstalled: r.keyInstalled };
    last = r;
    if (i < attempts - 1) await sleep(delay);
  }
  if (!last?.auth) {
    return { ok: false, authFailed: false, reason: `could not open an SSH session to the guest (${last?.msg ?? "unknown error"})` };
  }

  const applied = await deps.reapplyCredentials().catch(() => false);
  if (!applied) {
    return {
      ok: false,
      authFailed: true,
      reason:
        `the guest rejected the server's stored credentials (${last.msg}) and the guest agent could not re-apply them, ` +
        `so nothing was run on it`,
    };
  }
  for (let i = 0; i < 3; i++) {
    const r = await tryOnce();
    if (r.ok) return { ok: true, repaired: true, keyInstalled: r.keyInstalled };
    last = r;
    if (i < 2) await sleep(Math.min(delay, 5_000));
  }
  return {
    ok: false,
    authFailed: true,
    reason:
      `the stored root password was re-applied to this VM through the guest agent, and SSH still rejects it (${last.msg}) — ` +
      `the SSH address is reaching a DIFFERENT machine (check the node for a duplicate private IP), so nothing was run on it`,
  };
}

/** Is the machine on the far end of the SSH session the VM we built? */
export async function verifyGuestIdentity(
  withGuest: WithGuest,
  expected: { uuid: string | null; hostname: string | null }
): Promise<IdentityVerdict> {
  const out = await withGuest((sh) => sh.exec(GUEST_IDENTITY_CMD, GUEST_QUICK_MS));
  const got = parseGuestIdentity(out.stdout);
  return guestIdentityVerdict({ expectedUuid: expected.uuid, expectedHostname: expected.hostname, gotUuid: got.uuid, gotHostname: got.hostname });
}

/** Where the worker writes a re-run copy of the game setup. 0700, root-only (it carries per-server secrets). */
export const GAME_SETUP_PATH = "/root/nxeon-game-setup.sh";

/**
 * Launch a (fresh) game setup in the background: write it via STDIN, then
 * start it as its own transient systemd unit so it survives this SSH session
 * and any cloud-init cgroup cleanup. If one is already running, leave it.
 * Returns within two short execs, whatever the size of the download.
 */
export const LAUNCH_SETUP_CMD =
  `if pgrep -f 'nxeon-(game-)?setup\\.sh' >/dev/null 2>&1; then echo NXLAUNCH_RUNNING; exit 0; fi; ` +
  `install -m 600 /dev/null /var/log/nxeon-setup.log 2>/dev/null || true; ` +
  `if command -v systemd-run >/dev/null 2>&1 && systemd-run --unit=nxeon-game-setup-$(date +%s) --collect --no-block ` +
  `/bin/bash -c '${GAME_SETUP_PATH} >> /var/log/nxeon-setup.log 2>&1' >/dev/null 2>&1; then echo NXLAUNCH_OK; ` +
  `else setsid nohup ${GAME_SETUP_PATH} >> /var/log/nxeon-setup.log 2>&1 < /dev/null & echo NXLAUNCH_OK; fi`;

export async function relaunchGameSetup(
  withGuest: WithGuest,
  script: string
): Promise<{ launched: boolean; alreadyRunning: boolean; detail: string }> {
  return withGuest(async (sh) => {
    const probe = await sh.exec(`pgrep -f 'nxeon-(game-)?setup\\.sh' >/dev/null 2>&1 && echo NXLAUNCH_RUNNING || echo NXLAUNCH_IDLE`, GUEST_QUICK_MS);
    if (/NXLAUNCH_RUNNING/.test(probe.stdout)) return { launched: false, alreadyRunning: true, detail: "a setup run is already in progress" };
    const body = `#!/bin/bash\nset -x\n${script}\n`;
    const w = await sh.execInput(`install -m 700 /dev/null ${GAME_SETUP_PATH} && cat > ${GAME_SETUP_PATH} && echo NXWRITE_OK`, body, GUEST_WRITE_MS);
    if (!/NXWRITE_OK/.test(w.stdout)) return { launched: false, alreadyRunning: false, detail: `could not write ${GAME_SETUP_PATH} (${(w.stderr || w.stdout).trim().slice(0, 160)})` };
    const r = await sh.exec(LAUNCH_SETUP_CMD, GUEST_QUICK_MS);
    if (/NXLAUNCH_RUNNING/.test(r.stdout)) return { launched: false, alreadyRunning: true, detail: "a setup run is already in progress" };
    return { launched: /NXLAUNCH_OK/.test(r.stdout), alreadyRunning: false, detail: (r.stderr || r.stdout).trim().slice(0, 160) };
  });
}

/** One read-only startup sample (unit restarts, container state, setup state, game + setup log tails). */
export async function sampleStartup(withGuest: WithGuest, unit: string, container: string): Promise<StartupSample | null> {
  const cmd = startupProbeCommand(unit, container);
  const r = await withGuest((sh) => sh.exec(cmd, GUEST_QUICK_MS));
  return parseStartupProbe(r.stdout);
}

