// ---------------------------------------------------------------------------
// 5. Deterministic failures
// ---------------------------------------------------------------------------

/**
 * A PROVISION failure that a retry of the identical job cannot fix (the IP is
 * held by another VM; SSH reaches a different machine; the game exits on start
 * with this exact configuration). runJob (worker/index.ts) fails the job at once
 * instead of burning the remaining attempts on the same outcome.
 */
export class ProvisionStopError extends Error {
  readonly nxNoRetry = true;
  constructor(message: string) {
    super(message);
    this.name = "ProvisionStopError";
  }
}

export function isNoRetryError(e: unknown): boolean {
  return !!(e && typeof e === "object" && (e as { nxNoRetry?: unknown }).nxNoRetry === true);
}
EOF

