      setTimeoutFn: opts.setTimeoutFn ?? setTimeout,
      clearTimeoutFn: opts.clearTimeoutFn ?? clearTimeout,
    };
  }

  register(def: SweepDef): this {
    if (this.sweeps.has(def.name)) throw new Error(`sweep "${def.name}" registered twice`);
