    await withServerSsh(server as any, async (c) => {
      const id = parseGuestIdentity((await exec(c, GUEST_IDENTITY_CMD, QUICK_TIMEOUT_MS)).stdout);
      const v = guestIdentityVerdict({ expectedUuid: smbiosUuid(vmCfg?.smbios1), expectedHostname: server.hostname, gotUuid: id.uuid, gotHostname: id.hostname });
      add("identity", v.ok ? (v.how === "unverified" ? "WARN" : "PASS") : "FAIL", v.ok ? `reached VM ${server.vmid} (matched by ${v.how})` : v.reason);
      if (!v.ok) return; // never read another machine's state into this report

      if (unit && container) {
        const s = parseStartupProbe((await exec(c, startupProbeCommand(unit, container), QUICK_TIMEOUT_MS)).stdout);
        if (!s) add("container", "WARN", "startup probe printed nothing");
        else {
          add("container", s.container === "running" ? "PASS" : "FAIL", `container ${container}: ${s.container}${s.exitCode !== null && s.container !== "running" ? ` (exit ${s.exitCode})` : ""}`);
          add("setup", /\bfailed\b/.test(s.setupState) ? "FAIL" : "PASS", s.setupState ? `last setup state: ${s.setupState}` : "no setup state file (server predates 2026-10-02 setup)");
          const errs = lastErrorLines(s.log, 6);
          add("last-errors", errs.matched ? "WARN" : "PASS", errs.matched ? errs.lines.map((l) => redactSecrets(l, secrets)).join(" | ").slice(0, 600) : "no fatal-looking lines in the recent game output");
        }
        const u = (await exec(c, `systemctl show ${unit} -p ActiveState -p SubState -p NRestarts --no-pager 2>/dev/null; ` +
          `echo NXRECENT=$(journalctl -u ${unit} --since '-10 min' --no-pager -o cat 2>/dev/null | grep -c 'Scheduled restart job')`, QUICK_TIMEOUT_MS)).stdout;
        const active = /ActiveState=(\S+)/.exec(u)?.[1] ?? "?";
        const nr = /NRestarts=(\d+)/.exec(u)?.[1] ?? "?";
        const recent = Number(/NXRECENT=(\d+)/.exec(u)?.[1] ?? "0");
        add("unit", active === "active" && recent === 0 ? "PASS" : active === "active" && recent < 3 ? "WARN" : "FAIL",
          `${unit}.service ${active}; NRestarts=${nr} total, ${recent} automatic restart(s) in the last 10 min`);
        const img = (await exec(c, `docker inspect -f '{{.Config.Image}} {{.Image}}' ${container} 2>/dev/null; ` +
          `docker image inspect -f '{{join .RepoDigests ","}}' $(docker inspect -f '{{.Image}}' ${container} 2>/dev/null) 2>/dev/null`, QUICK_TIMEOUT_MS)).stdout.trim();
        add("image", img ? "PASS" : "FAIL", img ? img.replace(/\s+/g, " ").slice(0, 300) : "no image for the container");
      } else {
        add("container", "WARN", `family ${fam ?? "?"} has no unit/container mapping to inspect`);
      }
      const m = (await exec(c, `free -m | awk '/^Mem:/{print $2}'; df -Pm / | awk 'NR==2{print $2" "$4}'`, QUICK_TIMEOUT_MS)).stdout.trim().split("\n");
      guestMemMb = Number(m[0]);
      const [diskTotal, diskFree] = (m[1] ?? "").split(" ").map(Number);
      if (Number.isFinite(diskFree)) add("disk", diskFree > 2048 ? "PASS" : "WARN", `/ ${diskFree} MB free of ${diskTotal} MB`);
    });
  } catch (e) {
    add("identity", "FAIL", `SSH failed: ${String((e as Error)?.message ?? e).slice(0, 200)}`);
  }

  if (planMb) {
    const okGuest = guestMemMb !== null && guestMemMb >= planMb * 0.9;
    const okCfg = cfgMem === planMb;
    const okBalloon = cfgBalloon === null || cfgBalloon === 0 || cfgBalloon >= planMb;
    add("memory", okGuest && okCfg && okBalloon ? "PASS" : okGuest && okCfg ? "WARN" : "FAIL",
      `plan ${planMb} MB; Proxmox memory ${Number.isFinite(cfgMem) ? cfgMem : "?"} MB, balloon ${cfgBalloon ?? "unset"}; guest sees ${guestMemMb ?? "?"} MB`);
  }

  // ---- Ports: in-guest binding + external reachability
  if (fam && !checks.some((c) => c.name === "identity" && c.verdict === "FAIL")) {
    const publicHost = server.dedicatedIp?.address ?? node.publicIp;
    for (const jp of joinPortsFor(fam)) {
      const bound = await gamePortBoundInGuest(server as any, jp.port, jp.protocol);
      add(`ports-guest ${jp.port}/${jp.protocol}`, bound === true ? "PASS" : bound === false ? "FAIL" : "WARN", bound === true ? "bound in the container" : bound === false ? "nothing bound" : "could not read");
      const fwd = server.dedicatedIp ? jp.port : server.portForwards.find((f) => f.guestPort === jp.port && f.protocol === jp.protocol)?.publicPort;
      if (!fwd) {
        add(`ports-public ${jp.port}/${jp.protocol}`, "FAIL", "no public forward for this join port");
        continue;
      }
      if (jp.protocol === "tcp") {
        const r = await checkGamePortOpen(publicHost, fwd, "tcp", { timeoutMs: 10_000, intervalMs: 5_000 });
        add(`ports-public ${jp.port}/tcp`, r.ok ? "PASS" : "FAIL", `${publicHost}:${fwd} ${r.ok ? "accepts connections" : r.error}`);
      } else {
        const info = await queryInfo(publicHost, fwd, 2500).catch(() => null);
        add(`ports-public ${jp.port}/udp`, info ? "PASS" : "WARN",
          info ? `${publicHost}:${fwd} A2S: "${info.name}" ${info.players}/${info.maxPlayers}` : `${publicHost}:${fwd} gave no A2S answer (normal for a non-query port; the in-guest binding above is the evidence)`);
      }
    }
  }

  const o = overall(checks);
  if (asJson) {
    console.log(JSON.stringify({ server: server.hostname, id: server.id, clean: o.clean, checks }, null, 2));
  } else {
    console.log(`\n${server.hostname} (${server.id}) — VM ${server.vmid} on ${node.name}\n`);
    for (const c of checks) console.log(`  ${c.verdict.padEnd(4)}  ${c.name.padEnd(24)} ${c.detail}`);
    console.log(o.clean ? "\nCLEAN BILL OF HEALTH\n" : `\nNOT CLEAN — failed: ${o.failed.join(", ") || "none"}; warnings: ${o.warned.join(", ") || "none"}\n`);
  }
  await db.$disconnect();
  process.exit(o.clean ? 0 : 1);
}

if (process.argv[1] && /verify-game-provision/.test(process.argv[1])) {
  main().catch(async (e) => {
    console.error(e);
    await db.$disconnect().catch(() => {});
    process.exit(2);
  });
}

