input.content:
/**
 * Reproductions of the two failed 2026-10-02 provisions and the new behaviour
 * (docs/PROVISIONING-FIRST-BOOT-RCA-2026-10-02.md):
 *
 *   A. projectzomboid-syep3t (VM 645, node-5): blank ADMIN_USERNAME -> game exits
 *      on start every ~30 s under Restart=always; detected only after 3 x 300 s.
 *   B. valheim-gjjrv9 (VM 644, node-2): its private IP 10.20.1.101 was also
 *      configured on VMs 101/137/138; NAT delivered SSH to VM 101; the image
 *      pull died; retries minted a new management key the guest never saw.
 *
 * The generated setup script is EXECUTED here, against a fake `docker` /
 * `systemctl` in a temp dir (every absolute path it writes is rewritten into
 * the temp dir first, and the test refuses to run if any is left), so the
 * retry/idempotency claims are tested as shell, not as string matching.
 */
import { test } from "node:test";
import assert from "node:assert/strict";
import { mkdtempSync, writeFileSync, readFileSync, existsSync, chmodSync, rmSync } from "node:fs";
import { tmpdir } from "node:os";
import { join } from "node:path";
import { spawnSync } from "node:child_process";

import { validateConfig } from "../lib/game-config.ts";
import {
  applyGameConfigEnv,
  blankIdentityDefaults,
  buildGameSetupScript,
  wrapDockerGameService,
  registryMirrorPrelude,
  CREATE_ATTEMPTS,
} from "../worker/game-variant.ts";
import {
  ipsFromVmConfig,
  macsFromVmConfig,
  duplicatePrivateIps,
  nodeHeldIps,
  ipConflictReason,
  guestIdentityVerdict,
  parseGuestIdentity,
  smbiosUuid,
  classifyStartup,
  parseStartupProbe,
  startupProbeCommand,
  lastErrorLines,
  redactSecrets,
  formatGuestLines,
  secretValuesFromConfig,
  ProvisionStopError,
  isNoRetryError,
  shouldReuseManagementKey,
  type VmIpEntry,
  type StartupSample,
} from "../lib/provision-guard.ts";
import { ensureGuestAccess, relaunchGameSetup, isSshAuthError, GAME_SETUP_PATH, type GuestShell, type WithGuest } from "../worker/provision-guest.ts";
import { retryCheck } from "../worker/provision-health.ts";
import { pickFreeIp } from "../lib/ipam.ts";
import { auditNodeIps } from "../worker/ip-audit.ts";
import { SETUP_RUNCMD } from "../worker/cloud-init-parts.ts";

// The live catalog rows (OsTemplate.setupScript, read from prod 2026-10-02).
const PZ_CATALOG =
  "curl -fsSL https://get.docker.com | sh && docker run -d --name projectzomboid -e PUID=1000 -e PGID=1000 -p 16261:16261/udp -p 16262:16262/udp -p 27015:27015/tcp -e SERVER_NAME=servertest -e SERVER_BRANCH= -e ADMIN_USERNAME=admin -e ADMIN_PASSWORD=changeme12 -e RCON_PASSWORD=changeme12 -e MAX_PLAYERS=16 -v /opt/projectzomboid/config:/project-zomboid-config -v /opt/projectzomboid/server:/project-zomboid --restart unless-stopped indifferentbroccoli/projectzomboid-server-docker";
const VALHEIM_CATALOG =
  "curl -fsSL https://get.docker.com | sh && docker run -d --name valheim -p 2456-2458:2456-2458/udp -v /opt/valheim/config:/config -v /opt/valheim/data:/opt/valheim -e SERVER_NAME='Nxeon' -e WORLD_NAME='Nxeon' -e SERVER_PASS='changeme12' --restart unless-stopped lloesche/valheim-server";
// projectzomboid-syep3t's real Server.gameConfig (secrets replaced).
const SYEP3T_CONFIG = {
  PVP: true, Speed: "2", Zombies: "3", MaxPlayers: 16, PauseEmpty: true, PublicName: "Nxeon Zomboid Server",
  MEMORY_XMX_GB: 4, RCON_PASSWORD: "rconSecret1234", ADMIN_PASSWORD: "adminSecret1234", ADMIN_USERNAME: "",
};

// ===========================================================================
// A. Project Zomboid: blank ADMIN_USERNAME
// ===========================================================================

test("A1: the exact syep3t config no longer produces -e ADMIN_USERNAME='' (catalog 'admin' survives)", () => {
  const old = applyGameConfigEnv(PZ_CATALOG, "projectzomboid", SYEP3T_CONFIG);
  assert.match(old, /-e ADMIN_USERNAME=admin /);
  assert.doesNotMatch(old, /-e ADMIN_USERNAME=''/);
  // ... while a real choice is still honoured.
  assert.match(applyGameConfigEnv(PZ_CATALOG, "projectzomboid", { ADMIN_USERNAME: "boss" }), /-e ADMIN_USERNAME='boss'/);
  // Passwords are untouched by this rule (blank join passwords stay a valid choice).
  assert.match(applyGameConfigEnv(VALHEIM_CATALOG, "valheim", { SERVER_PASS: "" }), /-e SERVER_PASS=''/);
});

test("A2: new orders default ADMIN_USERNAME to 'admin'; provision persists 'admin' for old blank rows", () => {
  const v = validateConfig("projectzomboid", {});
  assert.ok(v.ok);
  assert.equal((v as any).values.ADMIN_USERNAME, "admin");
  assert.deepEqual(blankIdentityDefaults("projectzomboid", PZ_CATALOG, SYEP3T_CONFIG), { ADMIN_USERNAME: "admin" });
  assert.deepEqual(blankIdentityDefaults("projectzomboid", PZ_CATALOG, { ADMIN_USERNAME: "boss" }), {});
  assert.deepEqual(blankIdentityDefaults("valheim", VALHEIM_CATALOG, {}), {});
});

test("A3: the full build for syep3t carries a valid admin user and no shared placeholder secrets", () => {
  const out = buildGameSetupScript({ id: "x", osTemplate: { setupScript: PZ_CATALOG, family: "projectzomboid" }, gameConfig: SYEP3T_CONFIG })!;
  assert.match(out, /-e ADMIN_USERNAME=admin /);
  assert.match(out, /-e ADMIN_PASSWORD='adminSecret1234'/);
  assert.doesNotMatch(out, /changeme12/);
});

const PZ_LOG = [
  "Validating files...",
  "Success! App '380870' fully installed.",
  "LOG  : General     , 1759368080000> invalid username given to \"-adminusername\"",
  "LOG  : General     , 1759368080001> Server exited",
  "java.lang.NullPointerException: Cannot invoke \"zombie.network.GameServer.stop()\"",
  "ADMIN_PASSWORD=adminSecret1234",
].join("\n");

function sample(over: Partial<StartupSample>): StartupSample {
  return { restarts: 0, container: "exited", exitCode: 0, lastRunSeconds: 22, setupState: "2026-10-02T01:24:00Z ready", setupRunning: false, log: "", ...over };
}

test("A4: an exit-0 loop with a fatal line is FATAL after 2 restarts, with the game's own words, secrets redacted", () => {
  assert.equal(classifyStartup(0, sample({ restarts: 1, log: PZ_LOG })).kind, "wait");
  const v = classifyStartup(0, sample({ restarts: 2, log: PZ_LOG }));
  assert.equal(v.kind, "fatal");
  if (v.kind !== "fatal") return;
  assert.match(v.reason, /exits \(with code 0\) seconds after every start/);
  assert.ok(v.lines.some((l) => /invalid username given to "-adminusername"/.test(l)));
  const shown = formatGuestLines(v.lines, secretValuesFromConfig(SYEP3T_CONFIG));
  assert.doesNotMatch(shown, /adminSecret1234/);
  assert.match(shown, /invalid username/);
});

test("A5: without a recognisable line it takes 3 restarts; unknown readings never decide", () => {
  const quiet = "starting\nloading\n";
  assert.equal(classifyStartup(0, sample({ restarts: 2, log: quiet })).kind, "wait");
  assert.equal(classifyStartup(0, sample({ restarts: 3, log: quiet })).kind, "fatal");
  assert.equal(classifyStartup(-1, sample({ restarts: 30, log: PZ_LOG })).kind, "wait");
  assert.equal(classifyStartup(5, sample({ restarts: 6, container: "running", lastRunSeconds: null, log: "" })).kind, "wait");
  // The baseline is the count when the wait began, not 0 (a retry inherits attempt 1's 39 restarts).
  assert.equal(classifyStartup(39, sample({ restarts: 40, log: PZ_LOG })).kind, "wait");
});

test("A6: the port wait stops at the first fatal verdict instead of sitting out 31 attempts", async () => {
  let calls = 0;
  const r = await retryCheck(async () => ({ ok: false, error: "ECONNREFUSED" }), {
    timeoutMs: 300_000,
    intervalMs: 10_000,
    sleep: async () => {},
    shouldAbort: async (n) => (n === 9 ? "the game exits on start" : null),
  });
  calls = r.attempts;
  assert.equal(r.ok, false);
  assert.equal(calls, 9);
  assert.equal((r as any).aborted, true);
  assert.equal((r as any).error, "the game exits on start");
});

test("A7: deterministic failures are not retried (ProvisionStopError)", () => {
  assert.equal(isNoRetryError(new ProvisionStopError("x")), true);
  assert.equal(isNoRetryError(new Error("x")), false);
  assert.equal(isNoRetryError(null), false);
});

test("A8: the probe command is shell-inert and its output parses", () => {
  assert.throws(() => startupProbeCommand("pz; rm -rf /", "x"));
  assert.throws(() => startupProbeCommand("projectzomboid", "a b"));
  const cmd = startupProbeCommand("projectzomboid", "projectzomboid");
  assert.doesNotMatch(cmd, /pgrep -f/); // would match the SSH command line itself
  const out = [
    "NXSU_NR=7",
    "NXSU_CS=exited|0|2026-10-02T01:40:00.000000000Z|2026-10-02T01:40:24.500000000Z",
    "NXSU_ST=2026-10-02T01:23:00Z ready",
    "NXSU_SR=0",
    "NXSU_LOG_BEGIN",
    PZ_LOG,
    "NXSU_LOG_END",
    "NXSU_SLOG_BEGIN",
    "NXSU_SLOG_END",
  ].join("\n");
  const s = parseStartupProbe(out)!;
  assert.equal(s.restarts, 7);
  assert.equal(s.container, "exited");
  assert.equal(s.exitCode, 0);
  assert.equal(s.lastRunSeconds, 25);
  assert.equal(s.setupRunning, false);
  assert.match(s.log, /invalid username/);
});

test("A9: the generated unit backs off restarts and never start-limits a customer's Start", () => {
  const out = wrapDockerGameService(PZ_CATALOG, "projectzomboid");
  assert.match(out, /Restart=always/);
  assert.match(out, /RestartSteps=5/);
  assert.match(out, /RestartMaxDelaySec=120/);
  assert.match(out, /StartLimitIntervalSec=0/);
});

// ===========================================================================
// B. Valheim: duplicate private IP, killed pull, rotated credentials
// ===========================================================================

const VM101 = { name: "sausaugepro", ipconfig0: "ip=10.20.1.101/24,gw=10.20.1.1", net0: "virtio=BC:24:11:00:01:01,bridge=vmbr1", smbios1: "uuid=11111111-1111-1111-1111-111111111111" };
const VM137 = { ipconfig0: "ip=10.20.1.101/24,gw=10.20.1.1", net0: "virtio=BC:24:11:00:01:37,bridge=vmbr1" };
const VM138 = { ipconfig0: "ip=10.20.1.101/24,gw=10.20.1.1", net0: "virtio=BC:24:11:00:01:38,bridge=vmbr1" };
const VM644 = { name: "valheim-gjjrv9", ipconfig0: "ip=10.20.1.101/24,gw=10.20.1.1", net0: "virtio=BC:24:11:00:06:44,bridge=vmbr1", smbios1: "uuid=64464464-4644-6446-4464-464464464464" };
const VM106a = { ipconfig0: "ip=10.20.1.106/24,gw=10.20.1.1", net0: "virtio=BC:24:11:00:01:06,bridge=vmbr1" };
const VM106b = { ipconfig0: "ip=10.20.1.106/24,gw=10.20.1.1", net0: "virtio=BC:24:11:00:02:06,bridge=vmbr1" };

const entry = (vmid: number, cfg: Record<string, string>): VmIpEntry => ({ vmid, kind: "qemu", ips: ipsFromVmConfig(cfg), macs: macsFromVmConfig(cfg) });
const NODE2 = [entry(101, VM101), entry(137, VM137), entry(138, VM138), entry(644, VM644), entry(150, VM106a), entry(151, VM106b), entry(160, { ipconfig0: "ip=dhcp", net0: "virtio=BC:24:11:00:01:60,bridge=vmbr1" })];

test("B1: VM config parsing — ipconfigN/lxc netN IPs, MACs, dhcp ignored", () => {
  assert.deepEqual(ipsFromVmConfig(VM101), ["10.20.1.101"]);
  assert.deepEqual(ipsFromVmConfig({ net0: "name=eth0,bridge=vmbr1,hwaddr=AA:BB:CC:DD:EE:FF,ip=10.20.1.7/24,gw=10.20.1.1" }), ["10.20.1.7"]);
  assert.deepEqual(ipsFromVmConfig({ ipconfig0: "ip=dhcp" }), []);
  assert.deepEqual(macsFromVmConfig(VM101), ["bc:24:11:00:01:01"]);
  assert.equal(smbiosUuid(VM644.smbios1), "64464464-4644-6446-4464-464464464464");
});

test("B2: the node-2 duplicates are found (101/137/138/644 on .101, two VMs on .106)", () => {
  const d = duplicatePrivateIps(NODE2);
  assert.deepEqual(d.get("10.20.1.101"), [101, 137, 138, 644]);
  assert.deepEqual(d.get("10.20.1.106"), [150, 151]);
  assert.equal(d.size, 2);
});

test("B3: IPAM never hands out an address a node VM holds, even if the DB has no row for it", async () => {
  const range = { nodeId: "node-2", subnetPrefix: "10.20.1.", ipStart: 101, ipEnd: 110 } as any;
  const tx: any = {
    server: { findMany: async () => [] }, // the DB knew NOTHING about .101 (the incident)
    vmMove: { findMany: async () => [] },
  };
  assert.equal(await pickFreeIp(tx, range), "10.20.1.101", "DB-only = the old behaviour = the bug");
  const held = nodeHeldIps(NODE2, [{ ip: "10.20.1.102", mac: "bc:24:11:00:09:99", state: "REACHABLE" }], null);
  assert.equal(await pickFreeIp(tx, range, held), "10.20.1.103", ".101 (VM configs) and .102 (live ARP) are both skipped");
});

test("B4: a retry re-proves its own address: 644 keeping .101 is a conflict naming the other VMs", () => {
  const why = ipConflictReason("10.20.1.101", 644, NODE2, null);
  assert.match(why!, /already configured on VM 101, 137, 138/);
  // Its own config/ARP entry is not a conflict.
  const solo = [entry(644, VM644)];
  assert.equal(ipConflictReason("10.20.1.101", 644, solo, [{ ip: "10.20.1.101", mac: "bc:24:11:00:06:44", state: "REACHABLE" }]), null);
  // ARP answered by ANOTHER MAC (VM 101's) is.
  assert.match(ipConflictReason("10.20.1.101", 644, solo, [{ ip: "10.20.1.101", mac: "bc:24:11:00:01:01", state: "STALE" }])!, /answering ARP/);
  // A FAILED neighbour lookup is no evidence of use.
  assert.equal(ipConflictReason("10.20.1.101", 644, solo, [{ ip: "10.20.1.101", mac: null, state: "FAILED" }]), null);
});

test("B5: identity — SSH landing on VM 101 instead of 644 is refused before anything runs", () => {
