// ---- the generated setup script, executed -------------------------------

const FAKE_DOCKER = `#!/bin/bash
# Fake docker: state in $NXFAKE. create fails while $NXFAKE/pull_failures > 0.
S="$NXFAKE"; echo "docker $*" >> "$S/docker.log"
case "$1" in
  info) exit 0;;
  container) [ -e "$S/container" ]; exit $?;;
  inspect) [ -e "$S/container" ] || { echo "Error: No such object" >&2; exit 1; }; echo running; exit 0;;
  rm) rm -f "$S/container"; echo "rm" >> "$S/events"; exit 0;;
  create)
    n=$(cat "$S/pull_failures" 2>/dev/null || echo 0)
    if [ "$n" -gt 0 ]; then echo $((n-1)) > "$S/pull_failures"; echo 'failed to register layer: unexpected EOF' >&2; echo "pull-failed" >> "$S/events"; exit 1; fi
    shift; echo "$*" > "$S/container"; echo "created" >> "$S/events"; exit 0;;
esac
exit 0
`;

function runSetup(script: string, state: string, opts: { pullFailures?: number } = {}): { code: number; stateLines: string[]; events: string[]; out: string } {
  const bin = join(state, "bin");
  spawnSync("mkdir", ["-p", bin, join(state, "lib"), join(state, "systemd")]);
  writeFileSync(join(bin, "docker"), FAKE_DOCKER);
  chmodSync(join(bin, "docker"), 0o755);
  for (const stub of ["systemctl", "sleep", "curl"]) {
    writeFileSync(join(bin, stub), `#!/bin/bash\necho "${stub} $*" >> "$NXFAKE/${stub}.log"\nexit 0\n`);
    chmodSync(join(bin, stub), 0o755);
  }
  if (opts.pullFailures !== undefined) writeFileSync(join(state, "pull_failures"), String(opts.pullFailures));
  const sandboxed = script
    .replaceAll("/var/lib/nxeon", join(state, "lib"))
    .replaceAll("/etc/systemd/system", join(state, "systemd"));
  // Safety: refuse to run anything that still writes outside the temp dir.
  const stray = [...sandboxed.matchAll(/(?:>>?|install -m \d+ \/dev\/null|mkdir -p)\s+(\/[^\s;'"]+)/g)].map((m) => m[1]).filter((p) => !p.startsWith(state));
  assert.deepEqual(stray, [], `script would write outside the sandbox: ${stray.join(", ")}`);
  const r = spawnSync("bash", ["-c", sandboxed], { env: { PATH: `${bin}:/usr/bin:/bin`, NXFAKE: state }, encoding: "utf8" });
  const read = (p: string) => (existsSync(p) ? readFileSync(p, "utf8").trim().split("\n").filter(Boolean) : []);
  return { code: r.status ?? -1, stateLines: read(join(state, "lib", "game-setup.state")), events: read(join(state, "events")), out: `${r.stdout}\n${r.stderr}` };
}

