    assert.ok(r.stateLines.some((l) => /failed: docker create \(image pull\) failed 6 times/.test(l)), r.stateLines.join("\n"));
    assert.match(r.stateLines.at(-1)!, /failed: no container after setup/);
    // The worker's repair = re-run the same idempotent script once the network is back.
    writeFileSync(join(dir, "pull_failures"), "0");
    const r2 = runSetup(VALHEIM_SCRIPT_FOR_SHELL("NxeonZero26"), dir);
    assert.equal(r2.code, 0, r2.out);
    assert.match(r2.stateLines.at(-1)!, /ready$/);
  } finally {
    rmSync(dir, { recursive: true, force: true });
