    const again = runSetup(VALHEIM_SCRIPT_FOR_SHELL("NxeonZero26"), dir);
    assert.deepEqual(again.events, ["rm", "created"].slice(0, 0).concat(["rm", "created"]).slice(0, 0).length ? [] : again.events); // sanity
    assert.ok(again.stateLines.some((l) => /container present/.test(l)));
    assert.equal(again.events.filter((e) => e === "created").length, 1, "no second create on an identical re-run");
    const changed = runSetup(VALHEIM_SCRIPT_FOR_SHELL("AnotherPass99"), dir);
    assert.equal(changed.events.filter((e) => e === "created").length, 2, "a different config rebuilds the container");
    assert.match(readFileSync(join(dir, "container"), "utf8"), /SERVER_PASS='AnotherPass99'/);
  } finally {
    rmSync(dir, { recursive: true, force: true });
  }
});

