/**
 * Reproductions of the two failed 2026-10-02 provisions and the new behaviour
 * (docs/PROVISIONING-FIRST-BOOT-RCA-2026-10-02.md):
 *
 *   A. projectzomboid-syep3t (VM 645, node-5): blank ADMIN_USERNAME -> game exits
 *      on start every ~30 s under Restart=always; detected only after 3 x 300 s.
 *   B. valheim-gjjrv9 (VM 644, node-2): its private IP 10.20.1.101 was also
 *      configured on VMs 101/137/138; NAT delivered SSH to VM 101; the image
 *      pull died; retries minted a new management key the guest never saw.
 *
 * The generated setup script is EXECUTED here, against a fake `docker` /
 * `systemctl` in a temp dir (every absolute path it writes is rewritten into
 * the temp dir first, and the test refuses to run if any is left), so the
 * retry/idempotency claims are tested as shell, not as string matching.
 */
import { test } from "node:test";
import assert from "node:assert/strict";
import { mkdtempSync, writeFileSync, readFileSync, existsSync, chmodSync, rmSync } from "node:fs";
import { tmpdir } from "node:os";
import { join } from "node:path";
import { spawnSync } from "node:child_process";

import { validateConfig } from "../lib/game-config.ts";
import {
  applyGameConfigEnv,
  blankIdentityDefaults,
  buildGameSetupScript,
  wrapDockerGameService,
  registryMirrorPrelude,
  CREATE_ATTEMPTS,
} from "../worker/game-variant.ts";
import {
  ipsFromVmConfig,
  macsFromVmConfig,
  duplicatePrivateIps,
  nodeHeldIps,
  ipConflictReason,
  guestIdentityVerdict,
  parseGuestIdentity,
  smbiosUuid,
  classifyStartup,
  parseStartupProbe,
  startupProbeCommand,
  lastErrorLines,
  redactSecrets,
  formatGuestLines,
  secretValuesFromConfig,
  ProvisionStopError,
  isNoRetryError,
  shouldReuseManagementKey,
  type VmIpEntry,
  type StartupSample,
} from "../lib/provision-guard.ts";
import { ensureGuestAccess, relaunchGameSetup, isSshAuthError, GAME_SETUP_PATH, type GuestShell, type WithGuest } from "../worker/provision-guest.ts";
import { retryCheck } from "../worker/provision-health.ts";
import { pickFreeIp } from "../lib/ipam.ts";
import { auditNodeIps } from "../worker/ip-audit.ts";
import { SETUP_RUNCMD } from "../worker/cloud-init-parts.ts";

// The live catalog rows (OsTemplate.setupScript, read from prod 2026-10-02).
const PZ_CATALOG =
  "curl -fsSL https://get.docker.com | sh && docker run -d --name projectzomboid -e PUID=1000 -e PGID=1000 -p 16261:16261/udp -p 16262:16262/udp -p 27015:27015/tcp -e SERVER_NAME=servertest -e SERVER_BRANCH= -e ADMIN_USERNAME=admin -e ADMIN_PASSWORD=changeme12 -e RCON_PASSWORD=changeme12 -e MAX_PLAYERS=16 -v /opt/projectzomboid/config:/project-zomboid-config -v /opt/projectzomboid/server:/project-zomboid --restart unless-stopped indifferentbroccoli/projectzomboid-server-docker";
const VALHEIM_CATALOG =
  "curl -fsSL https://get.docker.com | sh && docker run -d --name valheim -p 2456-2458:2456-2458/udp -v /opt/valheim/config:/config -v /opt/valheim/data:/opt/valheim -e SERVER_NAME='Nxeon' -e WORLD_NAME='Nxeon' -e SERVER_PASS='changeme12' --restart unless-stopped lloesche/valheim-server";
// projectzomboid-syep3t's real Server.gameConfig (secrets replaced).
const SYEP3T_CONFIG = {
  PVP: true, Speed: "2", Zombies: "3", MaxPlayers: 16, PauseEmpty: true, PublicName: "Nxeon Zomboid Server",
  MEMORY_XMX_GB: 4, RCON_PASSWORD: "rconSecret1234", ADMIN_PASSWORD: "adminSecret1234", ADMIN_USERNAME: "",
};

// ===========================================================================
// A. Project Zomboid: blank ADMIN_USERNAME
// ===========================================================================

test("A1: the exact syep3t config no longer produces -e ADMIN_USERNAME='' (catalog 'admin' survives)", () => {
  const old = applyGameConfigEnv(PZ_CATALOG, "projectzomboid", SYEP3T_CONFIG);
