/** A fake guest: which credentials it accepts, and whether QGA has re-applied the password. */
function fakeGuest(opts: { acceptsStored: boolean; acceptsAfterRepair: boolean }) {
  let repaired = false;
  const commands: string[] = [];
  const shell: GuestShell = {
    exec: async (cmd) => {
      commands.push(cmd);
      return { code: 0, stdout: "", stderr: "" };
    },
    execInput: async (cmd, input) => {
      commands.push(`${cmd} <<< ${input.trim()}`);
      return { code: 0, stdout: "NXKEY_OK\n", stderr: "" };
    },
  };
  const withGuest: WithGuest = async (fn) => {
    const ok = repaired ? opts.acceptsAfterRepair : opts.acceptsStored;
    if (!ok) throw Object.assign(new Error("All configured authentication methods failed"), { level: "client-authentication" });
    return fn(shell);
  };
  return {
    withGuest,
    commands,
    reapply: async () => {
      repaired = true;
      return true;
    },
    get repaired() {
      return repaired;
    },
  };
}
const KEY = "ssh-ed25519 AAAAC3NzaC1lZDI1NTE5AAAAIFakeKeyForTestsOnly000000000000000000000000 nxeon-mgmt-cmuqa0f4b0006hl36891ycsnb";

