      if (cmd.includes("systemd-run")) return { code: 0, stdout: "NXLAUNCH_OK\n", stderr: "" };
      return { code: 0, stdout: "NXLAUNCH_IDLE\n", stderr: "" };
    },
    execInput: async (cmd, input) => {
      cmds.push({ cmd, input });
      return { code: 0, stdout: "NXWRITE_OK\n", stderr: "" };
