  assert.match(write.cmd, new RegExp(`install -m 700 /dev/null ${GAME_SETUP_PATH}`));
  assert.match(write.input!, /^#!\/bin\/bash\nset -x\necho game\n$/);
  assert.ok(cmds.some((c) => /systemd-run --unit=nxeon-game-setup-/.test(c.cmd)));
  assert.ok(cmds.every((c) => !/pgrep -f/.test(c.cmd)));
  running = true;
  cmds.length = 0;
  const r2 = await relaunchGameSetup(wg, "echo game");
